import org.junit.runner.RunWith;
import org.mockito.Mockito;

import static org.hamcrest.CoreMatchers.is;
import static org.junit.Assert.assertThat;
import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.Mockito.when;

@RunWith(MockitoJUnitRunner.class)
public class TagTest {

    @Test
    public void getName_AlreadyInitialized_ReturnsName() {
        String name = "div";
        when(Tag.valueOf(name)).thenReturn(new Tag(name));
        assertThat(Tag.valueOf(name).getName(), is(name));
    }

    @Test
    public void normalName_WithNormalizedString_ReturnsNormalizedName() {
        when(Normalizer.normalize(anyString())).thenReturn("div");
        assertThat(Tag.valueOf("   ").normalName(), is("div"));
    }

    @Test
    public void valueOf_UnknownTag_ReturnsNull() {
        Tag tag = Tag.valueOf("");
        assertThat(tag, is(null));
    }

    @Test
    public void valueOf_KnownTag_ReturnsInitializedTag() {
        when(ParseSettings.KNOWN_TAGS).thenReturn(new HashMap<String, String>() {{
            put("div", "div");
        }});
        Tag tag = Tag.valueOf("div");
        assertThat(tag.getName(), is("div"));
    }

    @Test
    public void isBlock_FormTag_ReturnsTrue() {
        when(ParseSettings.KNOWN_TAGS).thenReturn(new HashMap<String, String>() {{
            put("form", "block");
        }});
        Tag tag = Tag.valueOf("form");
        assertThat(tag.isBlock(), is(true));
    }

    @Test
    public void formatAsBlock_FormTag_ReturnsTrue() {
